//! Bundled practice boards, generated by the real engine. Not an offline infinite generator.
use puzzgen::puzzles::{Difficulty, GenerateRequest, PuzzleKind, generate};
fn main() -> Result<(), Box<dyn std::error::Error>> {
    let mut fixtures = Vec::new();
    for kind in PuzzleKind::ALL {
        for difficulty in [Difficulty::Easy, Difficulty::Medium, Difficulty::Hard] {
            fixtures.push(generate(GenerateRequest {
                kind,
                difficulty,
                seed: Some(42),
                include_solution: true,
                content_version: None,
            })?);
        }
    }
    let path = std::env::args().nth(1).ok_or("Pass a JSON output path")?;
    std::fs::write(path, serde_json::to_string_pretty(&fixtures)? + "\n")?;
    println!("Exported {} labeled practice boards", fixtures.len());
    Ok(())
}
